// Simulation : un lead enregistre, au format de l'API Graph (/{formulaire}/leads). Exemple. Donnees fictives.
const courriel = 'paul.exemple' + String.fromCharCode(64) + 'exemple.invalid';
return [{ json: { id: 'lead-0001', created_time: '2026-11-06T09:30:00+0100', field_data: [
  { name: 'full_name', values: ['Exemple. Paul'] },
  { name: 'email', values: [courriel] },
  { name: 'phone_number', values: ['+33600000000'] },
  { name: 'message', values: ['Exemple. Bonjour, je souhaite un devis pour une terrasse en bois.'] },
] } }];

// Gabarit Accueil, leads : un lead Facebook devient un message normalise (canal d'origine facebook_lead).
const cfg = $('Lire les réglages').first().json || {};
const org = $('Compte de cette copie').first().json.organisation_id;
const simulation = cfg.simulation !== false;
const coupe = cfg.interrupteur_general === false || cfg.interrupteur_departement === false;
const champ = (lead, nom) => { const f = (lead.field_data || []).find((x) => x.name === nom); return f && f.values && f.values[0] ? String(f.values[0]) : ''; };
const vus = new Set();
const sortie = [];
for (const it of $input.all()) {
  const l = it.json;
  const cle = 'fl:' + org + ':' + l.id;
  const courriel = champ(l, 'email').trim().toLowerCase();
  const tel = champ(l, 'phone_number').trim();
  let motif = null;
  if (coupe) motif = 'interrupteur_coupe';
  else if (!l.id) motif = 'sans_identifiant';
  else if (!courriel && !tel) motif = 'sans_contact';
  else if (vus.has(cle)) motif = 'doublon';
  if (!motif) vus.add(cle);
  sortie.push({ json: { organisation_id: org, simulation: simulation, source: 'facebook_lead', canal_origine: 'facebook_lead', cle: cle, ref_externe: String(l.id || ''), id_boite: '', fil_externe: '', conversation_cle: courriel ? 'c:' + courriel : 'tel:' + tel, de_adresse: courriel, de_nom: champ(l, 'full_name').slice(0, 120), telephone: tel, sujet: 'Demande reçue par Facebook Lead Ads', texte: (champ(l, 'message') || 'Demande de devis reçue par un formulaire Facebook.').slice(0, 4000), recu_le: l.created_time || new Date().toISOString(), a_photo: false, repondre_au_client: true, voie: motif ? 'ignorer' : 'deposer', motif: motif } });
}
return sortie;

// Simulation : rien n'est ecrit dans la plateforme ; le depot prevu part au journal.
const prevus = $input.all().map((it) => ({ effet: 'deposer_message', organisation_id: it.json.organisation_id, cle: it.json.cle, conversation_cle: it.json.conversation_cle, canal_origine: it.json.canal_origine }));
return [{ json: { simulation: true, effets_prevus: prevus, effets_faits: [] } }];
